async function appendAiGenerationAudit(ctx: any, slug: string, action: "narrative" | "comparison" | "bio-rewrite" | "title" | "tags" | "summary", status: "draft" | "approved" | "rejected" | "completed" | "failed", repositoryName?: string) {
  const db = await getDb();
  const connection = db ? null : localGet<{ login?: string } | null>(`githubConnection:${ctx.user.openId}`, null); const profile = db ? ((await db.select().from(profiles).where(and(eq(profiles.userId, ctx.user.id), eq(profiles.slug, slug))).limit(1))[0] || (await db.select().from(profiles).where(eq(profiles.userId, ctx.user.id)).limit(1))[0]) : localGet<any>(`profile:${slug}`, null) || (connection?.login ? localGet<any>(`profile:${connection.login.toLowerCase()}`, null) : null);
  if (!profile) return null;
  const config: any = profile.sectionConfig || {};
  const audit = Array.isArray(config.aiGenerationAudit) ? config.aiGenerationAudit : [];
  const entry = { id: `ai-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, action, status, repositoryName: repositoryName ? sanitizePlainText(repositoryName, 120) : undefined, createdAt: Date.now() };
  const sectionConfig = { ...config, aiGenerationAudit: [entry, ...audit].slice(0, 50) };
  if (db) await db.update(profiles).set({ sectionConfig }).where(eq(profiles.id, profile.id));
  else localSet(`profile:${slug}`, { ...profile, sectionConfig });
  return entry;
}

const demoProfile = { slug: "alexmorgan", displayName: "Alex Morgan", githubLogin: "alexmorgan", bio: "Product-minded engineer focused on interfaces, developer tools, and systems that help good ideas become useful things.", avatarUrl: "https://avatars.githubusercontent.com/u/583231?v=4", location: "London, UK", template: "atelier", isPublic: true, repositories: [{ name: "orbit-ui", description: "A small, intentional component system for expressive product interfaces.", language: "TypeScript", stars: 184, forks: 19, aiSummary: "A thoughtful UI foundation that balances accessible primitives with a strong visual point of view.", isPinned: true }, { name: "signal-cache", description: "Fast, typed caching for edge-first applications.", language: "Rust", stars: 92, forks: 8, aiSummary: "A compact caching layer designed for predictable performance and composable invalidation.", isPinned: true }] };
